inputs.css:
.header {
  width: 10px;
  height: 20px;
  background-color: "brown";
}
.green {
  color: #e6e7e0 !important;
  font-size: 30px;
  background-color: #0a0a0a;
  font-style: italic;
  font-weight: bolder;
  font-family: 'Lucida Sans', 'Lucida Sans Regular', 'Lucida Grande', 'Lucida Sans Unicode', Geneva, Verdana, sans-serif;
}
img {
  border-radius: 8px;
  border: solid 2px #181718;
}
#check-id {
  color: #80f711;
}
#check-id-2 {
  color: #f73f11;
}
#check-id-3 {
  color: #11f779;
}
#check-id-3 span {
  color: #5611f7;
}
#check-id-3 > small {
  color: rgba(247, 17, 159, 0.219);
}
#check-id-3 > small + strong {
  color: #3307f5;
  font-weight: bolder;
}
#check-id-3 > small + strong ~ blockquote {
  color: #141416;
  font-weight: bolder;
  font-size: 30px;
}
#check-id-3 > small + strong ~ blockquote:hover {
  color: #1744da;
}
#check-id-3 > small + strong ~ blockquote::first-letter {
  font-size: 50px;
}

.scoped-text {
  color: green !important;
  font-size: 10px;
}
.scoped-text-two {
  color: rgba(252, 160, 21, 0.959);
  font-size: 15px;
}
.scoped-text-three {
  color: #55afd3;
  font-size: 19px;
}
.scoped-text-four {
  color: rgba(211, 101, 147, 0.911);
  font-size: 25px;
}
